import React from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  spring,
  interpolate,
} from "remotion";
import { TransitionSeries, linearTiming } from "@remotion/transitions";
import { fade } from "@remotion/transitions/fade";

export const fps = 25;
export const durationInFrames = 254;

// Solid colors for ProRes alpha export — no rgba() on any "box" fill
const COLORS = {
  navy: "#16213E",         // card fill
  navyBorder: "#2A3450",   // card border
  navyLight: "#252E4C",    // mockup square (lighter than card)
  blue: "#00AAFF",
  green: "#4ADE80",
  greenBadge: "#1A3D2E",   // solid dark green — RESOLVED badge fill
  amber: "#FBBF24",
  red: "#EF4444",
  redBadge: "#3D1F2A",     // solid dark red — PRICE DROP badge fill
  muted: "#9CA3AF",
  white: "#FFFFFF",
};

const TRANSITION = 12;
const MONO = "'Courier New', monospace";
const SANS = "'Inter', sans-serif";

const SafeZone: React.FC<{ children: React.ReactNode }> = ({ children }) => (
  <div
    style={{
      position: "absolute",
      left: 250,
      top: 250,
      width: 3340,
      height: 1660,
      overflow: "hidden",
      fontFamily: SANS,
    }}
  >
    {children}
  </div>
);

// ============================================================
// SHARED — Timestamp with blinking colon + pulsing dot
// ============================================================
const Timestamp: React.FC<{
  time: string;
  timeColor: string;
  dotColor: string;
  frame: number;
  inProgress: number;
}> = ({ time, timeColor, dotColor, frame, inProgress }) => {
  const colonVisible = Math.floor(frame / 12) % 2 === 0 ? 1 : 0.15;
  const dotPulse = 0.4 + (Math.sin(frame / 8) * 0.5 + 0.5) * 0.6;
  const parts = time.split(":");
  return (
    <div
      style={{
        display: "flex",
        alignItems: "center",
        gap: 24,
        opacity: inProgress,
        transform: `translateY(${interpolate(inProgress, [0, 1], [-20, 0])}px)`,
      }}
    >
      <div
        style={{
          width: 20,
          height: 20,
          borderRadius: "50%",
          background: dotColor,
          opacity: dotPulse,
          boxShadow: `0 0 20px ${dotColor}`,
        }}
      />
      <div
        style={{
          fontFamily: MONO,
          fontSize: 72,
          fontWeight: 800,
          color: timeColor,
          letterSpacing: "0.05em",
          display: "flex",
          lineHeight: 1,
        }}
      >
        <span>{parts[0]}</span>
        <span style={{ opacity: colonVisible }}>:</span>
        <span>{parts[1]}</span>
      </div>
    </div>
  );
};

// ============================================================
// SHARED — Product mockup silhouette (280×280, solid fill)
// ============================================================
const ProductMockup: React.FC = () => (
  <div
    style={{
      width: 280,
      height: 280,
      borderRadius: 20,
      background: COLORS.navyLight,
      display: "flex",
      alignItems: "center",
      justifyContent: "center",
      flexShrink: 0,
    }}
  >
    <svg width="140" height="140" viewBox="0 0 24 24">
      <path
        d="M 12 3 L 21 7.5 L 12 12 L 3 7.5 Z"
        stroke={COLORS.muted}
        strokeWidth={1.5}
        strokeLinejoin="round"
        fill="none"
      />
      <path
        d="M 3 7.5 L 3 16.5 L 12 21 L 12 12"
        stroke={COLORS.muted}
        strokeWidth={1.5}
        strokeLinejoin="round"
        fill="none"
      />
      <path
        d="M 21 7.5 L 21 16.5 L 12 21"
        stroke={COLORS.muted}
        strokeWidth={1.5}
        strokeLinejoin="round"
        fill="none"
      />
    </svg>
  </div>
);

// Price font configuration — shared so $89.99 and $74.99 measure identically
const PRICE_FONT: React.CSSProperties = {
  fontFamily: MONO,
  fontSize: 180,
  fontWeight: 900,
  letterSpacing: "-0.02em",
  lineHeight: 1,
  whiteSpace: "nowrap",
};

// ============================================================
// PHASE 1 — Nighttime alert
// ============================================================
const Phase1: React.FC = () => {
  const frame = useCurrentFrame();

  // Entrances
  const tsIn = spring({ frame, fps: 25, delay: 0, config: { damping: 200 }, durationInFrames: 15 });
  const cardIn = spring({ frame, fps: 25, delay: 5, config: { damping: 200 }, durationInFrames: 20 });
  const cardScale = interpolate(cardIn, [0, 1], [0.92, 1]);
  const cardTy = interpolate(cardIn, [0, 1], [30, 0]);

  // Price flip
  const oldOut = interpolate(frame, [30, 45], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const newIn = interpolate(frame, [32, 47], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const r = Math.round(255 + (239 - 255) * newIn);
  const g = Math.round(255 + (68 - 255) * newIn);
  const b = Math.round(255 + (68 - 255) * newIn);
  const newPriceColor = `rgb(${r}, ${g}, ${b})`;

  // Arrow + percentage reveal at frame 45
  const arrowRowSpring = spring({
    frame,
    fps: 25,
    delay: 45,
    config: { damping: 200 },
    durationInFrames: 18,
  });
  const arrowRowTy = interpolate(arrowRowSpring, [0, 1], [20, 0]);

  // Badge at frame 55
  const badgeSpring = spring({
    frame,
    fps: 25,
    delay: 55,
    config: { damping: 200 },
    durationInFrames: 22,
  });
  const badgeScale = interpolate(badgeSpring, [0, 1], [0.8, 1]);
  const badgeTx = interpolate(badgeSpring, [0, 1], [40, 0]);
  const badgeGlow = 30 + (Math.sin(frame / 5) * 0.5 + 0.5) * 30;

  return (
    <AbsoluteFill style={{ fontFamily: SANS }}>
      <SafeZone>
        <div
          style={{
            position: "absolute",
            left: "50%",
            top: "50%",
            transform: "translate(-50%, -50%)",
            display: "flex",
            flexDirection: "column",
            alignItems: "center",
            gap: 60,
          }}
        >
          {/* Timestamp */}
          <Timestamp
            time="02:00 AM"
            timeColor={COLORS.white}
            dotColor={COLORS.red}
            frame={frame}
            inProgress={tsIn}
          />

          {/* Card group: badge stacked ABOVE card, right-aligned to card edge */}
          <div
            style={{
              display: "flex",
              flexDirection: "column",
              alignItems: "flex-end",
              gap: 24,
              opacity: cardIn,
              transform: `translateY(${cardTy}px) scale(${cardScale})`,
            }}
          >
            {/* PRICE DROP DETECTED badge — sits above the card, right-aligned */}
            <div
              style={{
                display: "inline-flex",
                alignItems: "center",
                gap: 16,
                padding: "20px 32px",
                background: COLORS.redBadge,
                border: `2px solid ${COLORS.red}`,
                borderRadius: 16,
                opacity: badgeSpring,
                transform: `translateX(${badgeTx}px) scale(${badgeScale})`,
                boxShadow: `0 0 ${badgeGlow}px rgba(239,68,68,0.55)`,
                whiteSpace: "nowrap",
                transformOrigin: "center right",
              }}
            >
              <svg width="40" height="40" viewBox="0 0 40 40">
                <path
                  d="M 20 5 L 37 34 L 3 34 Z"
                  stroke={COLORS.red}
                  strokeWidth={3}
                  strokeLinejoin="round"
                  fill="none"
                />
                <line
                  x1="20"
                  y1="16"
                  x2="20"
                  y2="26"
                  stroke={COLORS.red}
                  strokeWidth={3}
                  strokeLinecap="round"
                />
                <circle cx="20" cy="30" r="2" fill={COLORS.red} />
              </svg>
              <div
                style={{
                  fontFamily: SANS,
                  fontSize: 32,
                  fontWeight: 900,
                  color: COLORS.red,
                  textTransform: "uppercase",
                  letterSpacing: "0.08em",
                  lineHeight: 1,
                }}
              >
                PRICE DROP DETECTED
              </div>
            </div>

            {/* Product card — solid fill */}
            <div
              style={{
                display: "inline-flex",
                alignItems: "center",
                gap: 56,
                padding: 56,
                background: COLORS.navy,
                border: `2px solid ${COLORS.navyBorder}`,
                borderRadius: 28,
              }}
            >
              <ProductMockup />
              <div
                style={{
                  display: "flex",
                  flexDirection: "column",
                  alignItems: "flex-start",
                  gap: 24,
                }}
              >
                {/* Price stack — grid cell so both prices contribute to width */}
                <div
                  style={{
                    display: "grid",
                    gridTemplateColumns: "auto",
                    gridTemplateRows: "auto",
                    overflow: "hidden",
                  }}
                >
                  <div
                    style={{
                      gridColumn: 1,
                      gridRow: 1,
                      ...PRICE_FONT,
                      color: COLORS.white,
                      opacity: 1 - oldOut,
                      transform: `translateY(${-100 * oldOut}px)`,
                    }}
                  >
                    $89.99
                  </div>
                  <div
                    style={{
                      gridColumn: 1,
                      gridRow: 1,
                      ...PRICE_FONT,
                      color: newPriceColor,
                      opacity: newIn,
                      transform: `translateY(${interpolate(newIn, [0, 1], [100, 0])}px)`,
                    }}
                  >
                    $74.99
                  </div>
                </div>

                {/* Arrow + % row */}
                <div
                  style={{
                    display: "flex",
                    alignItems: "center",
                    gap: 20,
                    opacity: arrowRowSpring,
                    transform: `translateY(${arrowRowTy}px)`,
                  }}
                >
                  <svg width="48" height="48" viewBox="0 0 48 48">
                    <path
                      d="M 24 8 L 24 36 M 12 26 L 24 38 L 36 26"
                      stroke={COLORS.red}
                      strokeWidth={4}
                      strokeLinecap="round"
                      strokeLinejoin="round"
                      fill="none"
                    />
                  </svg>
                  <div
                    style={{
                      fontFamily: SANS,
                      fontSize: 72,
                      fontWeight: 800,
                      color: COLORS.red,
                      lineHeight: 1,
                    }}
                  >
                    -16.7%
                  </div>
                </div>
              </div>
            </div>
          </div>
        </div>
      </SafeZone>
    </AbsoluteFill>
  );
};

// ============================================================
// PHASE 2 — Already handled (mirrors Phase 1 layout)
// ============================================================
const Phase2: React.FC = () => {
  const frame = useCurrentFrame();

  // Price color shifts red -> muted over phase-local 0-20
  const colorShift = interpolate(frame, [0, 20], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const r = Math.round(239 + (156 - 239) * colorShift);
  const g = Math.round(68 + (163 - 68) * colorShift);
  const b = Math.round(68 + (175 - 68) * colorShift);
  const priceColor = `rgb(${r}, ${g}, ${b})`;
  const dimColor = priceColor;

  // Arrow + % fade to 0.4
  const arrowOpacity = interpolate(frame, [0, 20], [1, 0.4], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Continuous green glow on badge
  const badgeGlow = 20 + (Math.sin(frame / 5) * 0.5 + 0.5) * 20;

  return (
    <AbsoluteFill style={{ fontFamily: SANS }}>
      <SafeZone>
        <div
          style={{
            position: "absolute",
            left: "50%",
            top: "50%",
            transform: "translate(-50%, -50%)",
            display: "flex",
            flexDirection: "column",
            alignItems: "center",
            gap: 60,
          }}
        >
          {/* Timestamp — 07:14 AM, blue, green dot */}
          <Timestamp
            time="07:14 AM"
            timeColor={COLORS.blue}
            dotColor={COLORS.green}
            frame={frame}
            inProgress={1}
          />

          {/* Card group: RESOLVED badge above card */}
          <div
            style={{
              display: "flex",
              flexDirection: "column",
              alignItems: "flex-end",
              gap: 24,
            }}
          >
            {/* RESOLVED green badge */}
            <div
              style={{
                display: "inline-flex",
                alignItems: "center",
                gap: 16,
                padding: "20px 32px",
                background: COLORS.greenBadge,
                border: `2px solid ${COLORS.green}`,
                borderRadius: 16,
                boxShadow: `0 0 ${badgeGlow}px rgba(74,222,128,0.5)`,
                whiteSpace: "nowrap",
              }}
            >
              <svg width="40" height="40" viewBox="0 0 40 40">
                <circle cx="20" cy="20" r="18" fill={COLORS.green} />
                <path
                  d="M 12 21 L 18 27 L 29 15"
                  stroke="#FFFFFF"
                  strokeWidth={3.5}
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  fill="none"
                />
              </svg>
              <div
                style={{
                  fontFamily: SANS,
                  fontSize: 32,
                  fontWeight: 900,
                  color: COLORS.green,
                  textTransform: "uppercase",
                  letterSpacing: "0.08em",
                  lineHeight: 1,
                }}
              >
                RESOLVED
              </div>
            </div>

            {/* Product card — identical structure to Phase 1 */}
            <div
              style={{
                display: "inline-flex",
                alignItems: "center",
                gap: 56,
                padding: 56,
                background: COLORS.navy,
                border: `2px solid ${COLORS.navyBorder}`,
                borderRadius: 28,
              }}
            >
              <ProductMockup />
              <div
                style={{
                  display: "flex",
                  flexDirection: "column",
                  alignItems: "flex-start",
                  gap: 24,
                }}
              >
                {/* Single price */}
                <div
                  style={{
                    display: "grid",
                    gridTemplateColumns: "auto",
                    gridTemplateRows: "auto",
                  }}
                >
                  <div
                    style={{
                      gridColumn: 1,
                      gridRow: 1,
                      ...PRICE_FONT,
                      color: priceColor,
                    }}
                  >
                    $74.99
                  </div>
                </div>

                {/* Arrow + % row, dimmed */}
                <div
                  style={{
                    display: "flex",
                    alignItems: "center",
                    gap: 20,
                    opacity: arrowOpacity,
                  }}
                >
                  <svg width="48" height="48" viewBox="0 0 48 48">
                    <path
                      d="M 24 8 L 24 36 M 12 26 L 24 38 L 36 26"
                      stroke={dimColor}
                      strokeWidth={4}
                      strokeLinecap="round"
                      strokeLinejoin="round"
                      fill="none"
                    />
                  </svg>
                  <div
                    style={{
                      fontFamily: SANS,
                      fontSize: 72,
                      fontWeight: 800,
                      color: dimColor,
                      lineHeight: 1,
                    }}
                  >
                    -16.7%
                  </div>
                </div>
              </div>
            </div>
          </div>
        </div>
      </SafeZone>
    </AbsoluteFill>
  );
};

// ============================================================
// PHASE 3 — Three Checks
// ============================================================
const ChecklistRow: React.FC<{
  label: string;
  delay: number;
  frame: number;
}> = ({ label, delay, frame }) => {
  const rowIn = spring({
    frame,
    fps: 25,
    delay,
    config: { damping: 200 },
    durationInFrames: 15,
  });

  const fillProgress = interpolate(frame, [delay, delay + 8], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const checkDraw = interpolate(frame, [delay, delay + 14], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const flashOpacity = interpolate(frame, [delay, delay + 20], [1, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const underlineWidth = interpolate(frame, [delay + 14, delay + 28], [0, 100], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Animate circle fill from navyLight -> green with solid color interpolation
  // (no rgba) so it renders correctly against alpha background.
  const fr = Math.round(37 + (74 - 37) * fillProgress);    // #252E4C -> #4ADE80
  const fg = Math.round(46 + (222 - 46) * fillProgress);
  const fb = Math.round(76 + (128 - 76) * fillProgress);
  const fillColor = `rgb(${fr}, ${fg}, ${fb})`;

  const borderColor =
    fillProgress > 0.5 ? COLORS.green : COLORS.navyBorder;

  const checkLength = 60;
  const dashOffset = checkLength * (1 - checkDraw);

  // Flash overlay — kept semi-transparent intentionally; sits on top of solid
  // Phase 3 container card so it composites correctly even on alpha export.
  const flashBg = `rgba(74,222,128,${0.08 * flashOpacity})`;

  return (
    <div
      style={{
        position: "relative",
        display: "flex",
        alignItems: "center",
        justifyContent: "space-between",
        padding: "20px 24px",
        opacity: rowIn,
        transform: `translateY(${interpolate(rowIn, [0, 1], [20, 0])}px)`,
        background: flashBg,
        borderRadius: 12,
      }}
    >
      <div
        style={{
          fontFamily: SANS,
          fontSize: 64,
          fontWeight: 800,
          color: COLORS.white,
          letterSpacing: "-0.01em",
        }}
      >
        {label}
      </div>
      <div
        style={{
          width: 120,
          display: "flex",
          justifyContent: "center",
        }}
      >
        <div
          style={{
            width: 96,
            height: 96,
            borderRadius: "50%",
            background: fillColor,
            border: `4px solid ${borderColor}`,
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
          }}
        >
          <svg width="56" height="56" viewBox="0 0 24 24">
            <path
              d="M 5 12 L 10 17 L 19 7"
              stroke="#FFFFFF"
              strokeWidth={4}
              strokeLinecap="round"
              strokeLinejoin="round"
              fill="none"
              strokeDasharray={checkLength}
              strokeDashoffset={dashOffset}
            />
          </svg>
        </div>
      </div>
      <div
        style={{
          position: "absolute",
          left: 24,
          right: 24,
          bottom: 0,
          height: 2,
          background: COLORS.green,
          width: `calc(${underlineWidth}% - 0px)`,
          maxWidth: "calc(100% - 48px)",
          borderRadius: 1,
          boxShadow: `0 0 8px ${COLORS.green}`,
        }}
      />
    </div>
  );
};

const Phase3: React.FC = () => {
  const frame = useCurrentFrame();
  const containerIn = spring({
    frame,
    fps: 25,
    delay: 0,
    config: { damping: 200 },
    durationInFrames: 20,
  });

  const glowOpacity = interpolate(frame, [77, 89], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const glowPulse = 40 + Math.sin(frame / 8) * 15;

  const captionSpring = spring({
    frame,
    fps: 25,
    delay: 78,
    config: { damping: 200 },
    durationInFrames: 20,
  });

  return (
    <AbsoluteFill style={{ fontFamily: SANS }}>
      <SafeZone>
        <div
          style={{
            position: "absolute",
            left: "50%",
            top: "50%",
            transform: `translate(-50%, -50%) translateY(${interpolate(
              containerIn,
              [0, 1],
              [40, 0]
            )}px)`,
            width: 2200,
            padding: "80px 100px",
            background: COLORS.navy,
            border: `2px solid ${COLORS.navyBorder}`,
            borderRadius: 32,
            opacity: containerIn,
            boxShadow: `0 0 ${glowPulse}px rgba(74,222,128,${0.2 * glowOpacity})`,
            display: "flex",
            flexDirection: "column",
            gap: 56,
          }}
        >
          <ChecklistRow label="Price adjusted" delay={0} frame={frame} />
          <ChecklistRow label="Change logged" delay={26} frame={frame} />
          <ChecklistRow label="Team notified" delay={49} frame={frame} />
        </div>

        <div
          style={{
            position: "absolute",
            left: 0,
            right: 0,
            bottom: 40,
            textAlign: "center",
            opacity: captionSpring,
            transform: `translateY(${interpolate(captionSpring, [0, 1], [20, 0])}px)`,
            fontFamily: SANS,
            fontSize: 32,
            fontWeight: 500,
            color: COLORS.muted,
            letterSpacing: "0.1em",
          }}
        >
          — Automatic resolution flow —
        </div>
      </SafeZone>
    </AbsoluteFill>
  );
};

// ============================================================
// MAIN COMPOSITION
// ============================================================
const MainComposition: React.FC = () => {
  return (
    <TransitionSeries>
      <TransitionSeries.Sequence durationInFrames={102}>
        <Phase1 />
      </TransitionSeries.Sequence>
      <TransitionSeries.Transition
        presentation={fade()}
        timing={linearTiming({ durationInFrames: TRANSITION })}
      />

      <TransitionSeries.Sequence durationInFrames={62}>
        <Phase2 />
      </TransitionSeries.Sequence>
      <TransitionSeries.Transition
        presentation={fade()}
        timing={linearTiming({ durationInFrames: TRANSITION })}
      />

      <TransitionSeries.Sequence durationInFrames={90}>
        <Phase3 />
      </TransitionSeries.Sequence>
    </TransitionSeries>
  );
};

export default MainComposition;
